import {courseProgressCSV,progressLabel,progressLabels} from './course-progress-export.mjs';
export function createProgressUI({e,api,ui,link}){let current=null,csvURL='';const staff=()=>ui.actor().role!=='student';
 const option=(v,t,s)=>'<option value="'+e(v)+'" '+(v===s?'selected':'')+'>'+e(t)+'</option>';
 function tabs(active){const items=staff()?[['progress','Class overview'],['insights','Question insights']]:[['grades','Grades & skills'],['path','Learning path']];return '<nav class="course-progress-tabs" aria-label="Progress views">'+items.map(([v,t])=>link(t,{view:v}).replace('<a ',v===active?'<a aria-current="page" ':'<a ')).join('')+'</nav>';}
 async function overview(params){const q=new URLSearchParams();for(const k of ['classId','search','filter'])if(params.get(k))q.set(k,params.get(k));const d=await api('course-progress?'+q);current=d;const units=d.units,offset=Math.max(0,Number(params.get('unitOffset'))||0),shown=units.slice(offset,offset+4),rowOffset=Math.max(0,Number(params.get('rowOffset'))||0),rows=d.rows.slice(rowOffset,rowOffset+12),route={view:'progress',...(d.class?{classId:d.class.id}:{}),...(params.get('filter')?{filter:params.get('filter')}:{}),...(params.get('search')?{search:params.get('search')}:{})};
  return tabs('progress')+'<div class="learning-section-title"><h2>Class learning progress</h2>'+(units.length?'<button type="button" class="btn" id="course-progress-export">Download filtered overview</button>':'')+'</div><form id="course-progress-filters" class="community-filters"><label>Class <select name="classId">'+d.classes.map(c=>option(c.id,c.name+(c.units?' · '+c.units+' units':''),d.class?.id)).join('')+'</select></label><label>Show <select name="filter">'+[['','All students'],['overdue','Overdue work'],['pending','Work waiting to be marked'],['working','Working / revising'],['complete','All units complete']].map(([v,t])=>option(v,t,params.get('filter')||'')).join('')+'</select></label><label>Find a student <input name="search" value="'+e(params.get('search')||'')+'" maxlength="120" placeholder="Name or number"></label></form><div class="learning-stats course-overview-stats"><div><strong>'+d.summary.students+'</strong><span>Students in class</span></div><div><strong>'+d.summary.overdue+'</strong><span>With overdue work</span></div><div><strong>'+d.summary.pending+'</strong><span>Awaiting marking</span></div><div><strong>'+d.summary.complete+'</strong><span>All units complete</span></div></div><p class="muted">Completion means assigned work has been handed in or reading confirmed. Grades and mastery are shown in their own views.</p>'+(units.length?'<div class="learning-section-title"><p>'+d.rows.length+' matching students · Units '+(offset+1)+'–'+Math.min(offset+4,units.length)+' of '+units.length+'</p><div class="vle-actions">'+(offset?link('← Earlier units',{...route,unitOffset:Math.max(0,offset-4)}):'')+(offset+4<units.length?link('Later units →',{...route,unitOffset:offset+4}):'')+'</div></div><div class="vle-panel table-wrap course-progress-table"><table class="data-table"><thead><tr><th>Student</th>'+shown.map(u=>'<th>'+link(u.order+'. '+u.title,{class:d.class.id,tab:'units',unit:u.id})+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr><th scope="row">'+link(r.name,{view:'path',classId:d.class.id,studentId:r.id})+'</th>'+shown.map(u=>{const c=r.cells.find(c=>c.id===u.id);return '<td><a class="course-progress-cell progress-'+e(c.status)+'" href="#/classroom?'+new URLSearchParams({view:'path',classId:d.class.id,studentId:r.id,unit:u.id})+'" title="'+e(c.reason||'Open progress and work')+'"><strong>'+e(progressLabel(c))+'</strong>'+(c.feedback?'<small>'+c.feedback+' unread feedback</small>':'')+'</a></td>';}).join('')+'</tr>').join('')+'</tbody></table>'+(!rows.length?'<p class="learning-empty">No students match these filters.</p>':'')+'</div><nav class="updates-pagination" aria-label="Student pages">'+(rowOffset?link('← Previous students',{...route,unitOffset:offset,rowOffset:Math.max(0,rowOffset-12)}):'')+(rowOffset+12<d.rows.length?link('More students →',{...route,unitOffset:offset,rowOffset:rowOffset+12}):'')+'</nav>':'<section class="learning-empty"><h3>No course units in this class yet.</h3><p>'+ (d.class?link('Add a unit in this classroom →',{class:d.class.id,tab:'units'}):'No classes are allocated to this account.')+'</p></section>');
 }
 async function path(params){const q=new URLSearchParams();for(const k of ['classId','studentId'])if(params.get(k))q.set(k,params.get(k));const d=await api('learning-path?'+q),isStudent=d.student,selected=params.get('unit'),paths=d.paths.filter(p=>p.units.length),filters={view:'path',...(!isStudent?{studentId:d.learner.id}:{})},all=paths.flatMap(p=>p.units);if(selected&&!all.some(u=>u.id===selected))throw Error('This unit is not in this learning path.');const next=d.next;
  return tabs(isStudent?'path':'progress')+(!isStudent?'<p>'+link('← Class overview',{view:'progress',classId:params.get('classId')||d.paths[0]?.classId||''})+'</p>':'')+'<div class="learning-section-title"><h2>'+(isStudent?'My learning path':e(d.learner.name)+' · Learning path')+'</h2><form id="learning-path-filters"><label>Class <select name="classId">'+option('','All classes',params.get('classId')||'')+d.classes.map(c=>option(c.id,c.name,params.get('classId'))).join('')+'</select></label></form></div><div class="learning-stats"><div><strong>'+d.summary.complete+' / '+d.summary.units+'</strong><span>Units complete</span></div><div><strong>'+d.summary.overdue+'</strong><span>Overdue tasks</span></div><div><strong>'+d.summary.feedback+'</strong><span>Unread feedback</span></div></div>'+(next&&isStudent?'<section class="learning-next"><div><small>YOUR NEXT STEP</small><strong>'+e(next.title)+'</strong><span>'+e(next.className)+'</span></div>'+link(next.label+' →',next.target).replace('<a ','<a class="btn primary" ')+'</section>':'')+'<p class="muted">A complete unit records handed-in work or confirmed reading. You can revisit it and continue improving your work.</p>'+(selected?'<p>'+link('Show all units',{...filters,...(params.get('classId')?{classId:params.get('classId')}:{})})+'</p>':'')+paths.map(p=>{const units=selected?p.units.filter(u=>u.id===selected):p.units;if(!units.length)return '';return '<section class="path-class"><div class="learning-section-title"><h3>'+e(p.className)+'</h3>'+link('Open classroom',{class:p.classId,tab:'units'})+'</div>'+units.map((u,i)=>(i===4?'<details class="vle-panel"><summary>Show '+(units.length-4)+' more units</summary>':'')+'<article class="vle-panel path-unit"><div class="learning-section-title"><h3>'+u.order+'. '+e(u.title)+'</h3><span class="course-progress-cell progress-'+e(u.status)+'">'+e(progressLabel(u))+'</span></div>'+(!u.available?'<p class="vle-note">'+e(u.reason)+'</p>':u.status==='scheduled'?'<p>More assigned work opens later. Check back when your teacher releases it.</p>':u.reading?'<p>'+(u.complete?'Reading completed. You can revisit this material.':'Read the material, then confirm completion on the unit page.')+'</p>':'')+(u.available||!isStudent?'<p>'+link('Read unit material →',{class:p.classId,tab:'units',unit:u.id})+'</p>':'')+(u.tasks.length?'<details '+(selected||u.overdue||u.feedback?'open':'')+'><summary>Assigned work · '+u.tasks.length+'</summary><div class="path-work">'+u.tasks.map(t=>'<div><span><strong>'+link(t.title,{class:p.classId,assignment:t.id,...(!isStudent?{review:d.learner.id}:{})})+'</strong><small>'+e(t.due?'Due '+t.due:'No deadline')+(t.feedbackUnread?' · Read feedback':'')+(!t.available?' · Hidden from student until released':'')+'</small></span><span>'+e(({returned:'Returned',submitted:'Handed in',revising:'Revising',overdue:'Overdue',draft:'In progress',assigned:'To do',scheduled:'Opens later'})[t.status])+(t.mark!==null&&t.maximum>0?'<small>'+t.mark+'/'+t.maximum+'</small>':'')+'</span></div>').join('')+'</div></details>':'')+'</article>'+((i===units.length-1&&units.length>4)?'</details>':'')).join('')+'</section>';}).join('')+(!paths.length?'<p class="learning-empty">No units have been added here yet. '+link('Open classrooms to see your classwork',{view:'classes'})+'</p>':'');
 }
 function bind(root){const data=current;const navigate=f=>{location.hash='/classroom?'+new URLSearchParams({view:'progress',...Object.fromEntries(new FormData(f))});};root.querySelector('#course-progress-filters')?.addEventListener('change',ev=>navigate(ev.currentTarget));root.querySelector('#course-progress-filters')?.addEventListener('submit',ev=>{ev.preventDefault();navigate(ev.currentTarget);});root.querySelector('#learning-path-filters')?.addEventListener('change',ev=>{const p=new URLSearchParams(location.hash.split('?')[1]);p.delete('unit');p.set('classId',new FormData(ev.currentTarget).get('classId'));location.hash='/classroom?'+p;});root.querySelector('#learning-path-filters')?.addEventListener('submit',ev=>ev.preventDefault());root.querySelector('#course-progress-export')?.addEventListener('click',()=>{if(csvURL)URL.revokeObjectURL(csvURL);csvURL=URL.createObjectURL(new Blob([courseProgressCSV(data)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=csvURL;a.download='WIST-class-progress.csv';a.click();});}
 return{overview,path,tabs,bind};
}
